import{_ as e,a as o,b as r,c as a,d as n}from"./chunks/animate.P06UtnDm.js";import{_ as s,o as i,c as l,a2 as g}from"./chunks/framework.Bzj1XTnB.js";const w=JSON.parse('{"title":"Select, move, crop and animate","description":"Use the lasso to pick up part of a drawing, then move, resize, rotate, flip, crop, animate or copy it.","frontmatter":{"lang":"en","slug":"selection","order":4,"title":"Select, move, crop and animate","description":"Use the lasso to pick up part of a drawing, then move, resize, rotate, flip, crop, animate or copy it."},"headers":[],"relativePath":"selection.md","filePath":"selection.md"}'),h={name:"selection.md"};function d(c,t,p,m,u,b){return i(),l("div",null,[...t[0]||(t[0]=[g('<h1 id="select-move-crop-and-animate" tabindex="-1">Select, move, crop and animate <a class="header-anchor" href="#select-move-crop-and-animate" aria-label="Permalink to &quot;Select, move, crop and animate&quot;">​</a></h1><h2 id="select-with-the-lasso" tabindex="-1">Select with the lasso <a class="header-anchor" href="#select-with-the-lasso" aria-label="Permalink to &quot;Select with the lasso&quot;">​</a></h2><ol><li>Choose <strong>Lasso</strong> in the toolbar.</li><li>Draw a loop around what you want. It doesn&#39;t have to be neat — Toonik picks up just the drawing inside the loop and fits the box tightly around it.</li><li>The drawing now floats in a box you can change.</li></ol><p><strong>Tip:</strong> double-tap the Lasso tool to select everything on the layer.</p><p><img src="'+e+'" alt="A selection with its handles"></p><h2 id="the-box" tabindex="-1">The box <a class="header-anchor" href="#the-box" aria-label="Permalink to &quot;The box&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Inside the box</strong></td><td>Drag to move it</td></tr><tr><td><strong>White round corners</strong></td><td>Drag to make it bigger or smaller (keeps its shape)</td></tr><tr><td><strong>White bars on the edges</strong></td><td>Drag to stretch it wider or taller</td></tr><tr><td><strong>↻ button below the box</strong></td><td>Drag around to rotate. It clicks into place at every 15°</td></tr><tr><td><strong>⋯ button above the box</strong></td><td>More options (see below)</td></tr><tr><td><strong>Two fingers on the box</strong></td><td>Pinch to resize and twist to rotate</td></tr></tbody></table><p><strong>Tap outside the box</strong> to put the drawing down. Press <strong>Back</strong> to cancel and leave everything as it was.</p><p>You can move a selection into the room around the canvas too (see <em>Images, video and objects</em>).</p><h2 id="the-bar-under-the-box" tabindex="-1">The bar under the box <a class="header-anchor" href="#the-bar-under-the-box" aria-label="Permalink to &quot;The bar under the box&quot;">​</a></h2><p><strong>Trsf</strong> (move, resize, rotate), <strong>Persp</strong> (drag each corner freely for a perspective look), <strong>Move</strong> (exact placement, below), <strong>Flip</strong> (left–right), <strong>Flip</strong> (up–down), <strong>Crop</strong>, <strong>Animate</strong> and <strong>Erase</strong> (delete what is selected).</p><h2 id="move-it-exactly" tabindex="-1">Move it exactly <a class="header-anchor" href="#move-it-exactly" aria-label="Permalink to &quot;Move it exactly&quot;">​</a></h2><p>When a finger is not precise enough, tap <strong>Move</strong>. Arrows appear above the bar:</p><p><img src="'+o+'" alt="Moving a selection with the arrows"></p><ul><li><strong>Tap an arrow</strong> to move the selection one step, or <strong>hold it</strong> to keep moving.</li><li><strong>X</strong> and <strong>Y</strong> show where the top left of the box is on the canvas, in pixels.</li><li>The button on the right switches the step between <strong>1 px</strong> and <strong>10 px</strong>.</li></ul><h2 id="the-⋯-menu" tabindex="-1">The ⋯ menu <a class="header-anchor" href="#the-⋯-menu" aria-label="Permalink to &quot;The ⋯ menu&quot;">​</a></h2><p><img src="'+r+'" alt="Selection options"></p><p>Choose <strong>Transform</strong> or <strong>Perspective</strong>, <strong>Add to selection</strong> or <strong>Remove from selection</strong>, or <strong>Crop</strong>, <strong>Flip horizontally</strong>, <strong>Flip vertically</strong> and <strong>Delete</strong>.</p><h3 id="add-to-or-remove-from-a-selection" tabindex="-1">Add to or remove from a selection <a class="header-anchor" href="#add-to-or-remove-from-a-selection" aria-label="Permalink to &quot;Add to or remove from a selection&quot;">​</a></h3><p>Tap <strong>Add to selection</strong> or <strong>Remove from selection</strong> in the ⋯ menu. The box steps aside and the selection shows as a dotted outline. Now every loop you draw is added to it (<strong>Add</strong>), or cut out of it (<strong>Remove</strong>) — switch between the two on the bar below. Draw as many loops as you like; pinch to zoom in for small parts. Tap <strong>Done</strong> (or Back) and the box comes back around everything selected, ready to move, flip or animate.</p><h2 id="crop" tabindex="-1">Crop <a class="header-anchor" href="#crop" aria-label="Permalink to &quot;Crop&quot;">​</a></h2><p>Trim a picture you added, or anything you selected.</p><p><img src="'+a+'" alt="Crop"></p><ul><li>Drag the <strong>corners</strong> and <strong>edges</strong>, or drag inside to move the crop box.</li><li>Pick a shape: <strong>Free</strong>, <strong>1:1</strong>, <strong>4:3</strong>, <strong>3:4</strong>, <strong>16:9</strong> or <strong>9:16</strong>.</li><li><strong>Trim edges</strong> cuts away empty, see-through margins in one tap.</li><li><strong>Reset</strong> starts again. <strong>Apply</strong> keeps the cropped part exactly where it was, still selected.</li></ul><h2 id="animate-a-selection" tabindex="-1">Animate a selection <a class="header-anchor" href="#animate-a-selection" aria-label="Permalink to &quot;Animate a selection&quot;">​</a></h2><p>Turn the selected drawing into a movement in one go — Toonik draws all the frames for you.</p><p><img src="'+n+'" alt="Animate selection"></p><ol><li>Tap <strong>Animate</strong>.</li><li>Pick a <strong>Preset</strong> (Move left to right, Bounce, Spin, Grow, Shrink, Fade in, Fade out, Shake, Float…), or set it up yourself: choose <strong>Start</strong> or <strong>End</strong>, then set <strong>Position</strong> (drag the S and E handles on the preview, or use <strong>X</strong> and <strong>Y</strong>: the slider gets close, <strong>−</strong> and <strong>+</strong> move one pixel, and holding them keeps going), <strong>Scale</strong>, <strong>Rotation</strong> and <strong>Opacity</strong>. To place a handle precisely, tap the <strong>magnifier</strong> in the corner of the preview for a close-up of it (tap again to see the whole stage), or pinch the preview with two fingers; one finger moves around while zoomed in.</li><li>Under <strong>Timing</strong>, choose how many <strong>Frames</strong> it lasts, the <strong>Easing</strong> (Linear, Ease in, Ease out, Bounce, Elastic…), how many times to <strong>Repeat</strong>, and <strong>Back and forth</strong>.</li><li>Tap <strong>Create animation</strong>. The movement is put on a new layer called &quot;Animation&quot;.</li></ol><h2 id="copy-to-another-frame" tabindex="-1">Copy to another frame <a class="header-anchor" href="#copy-to-another-frame" aria-label="Permalink to &quot;Copy to another frame&quot;">​</a></h2><ol><li>Select the drawing with the lasso.</li><li>Tap <strong>Copy</strong> in the bottom bar.</li><li>Go to another frame and tap <strong>Paste</strong>. The copy appears <strong>in the same spot</strong>, still selected, so you can nudge it before putting it down.</li></ol><h2 id="save-as-an-object" tabindex="-1">Save as an object <a class="header-anchor" href="#save-as-an-object" aria-label="Permalink to &quot;Save as an object&quot;">​</a></h2><p>Keep a drawing to use again in any project: open <strong>⋮ → Save as object</strong>, choose <strong>Selection</strong>, <strong>Current layer</strong> or <strong>Animation</strong> (a range of frames), give it a name and tags, and tap <strong>Save object</strong>. It appears in the Object library.</p>',32)])])}const y=s(h,[["render",d]]);export{w as __pageData,y as default};
